document.addEventListener("DOMContentLoaded",function(){const more=document.getElementById("more-button"),less=document.getElementById("less-button"),section=document.getElementById("category-section");less&&more&&section&&(less.addEventListener("click",function(){more.style.display="block",less.style.display="none",section.style.height="35px",section.style.maxWidth="60%"}),more.addEventListener("click",function(){less.style.display="block",more.style.display="none",section.style.height="100%",section.style.maxWidth="80%"}));const categoryLinks=document.querySelectorAll("#category-section .category .option");function updateDataAttribute(){var element=document.getElementById("img-bot");element&&(window.innerWidth<=1e3?element.setAttribute("data-rellax-speed","0.4"):element.setAttribute("data-rellax-speed","1.5"))}categoryLinks.length>0&&categoryLinks.forEach(function(link){link.addEventListener("click",function(){categoryLinks.forEach(function(otherLink){otherLink.classList.remove("active-cat")}),this.classList.add("active-cat")})}),updateDataAttribute(),window.addEventListener("resize",updateDataAttribute)});